import time
import random

def retry_call(func, attempts):
    for step in range(attempts):
        value = func()
        if value is not None:
            return value
        time.sleep(random.random())
    return None

def title_case(phrase):
    pieces = phrase.split(' ')
    out = [p.capitalize() for p in pieces]
    return ' '.join(out)

def dedupe(seq):
    seen = set()
    result = []
    for item in seq:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def clamp(value, low, high):
    if value < low:
        return low
    if value > high:
        return high
    return value

def format_row(cells):
    text = ', '.join(str(c) for c in cells)
    return text
